Recover remaining redo on oakland , and fail over to the new primary role: SQL> ALTER DATABASE RECOVER MANAGED STANDBY DATABASE CANCEL;
SQL> ALTER DATABASE RECOVER MANAGED STANDBY FINISH;
SQL> ALTER DATABASE FAILOVER TO OAKLAND;
SQL> ALTER DATABASE OPEN; Configure log archive destinations on oakland , as necessary: SQL> ALTER SYSTEM SET LOG_ARCHIVE_DEST_2='service="boston" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, PRIMARY_ROLE)
  3  DB_UNIQUE_NAME="oakland"'; SQL> ALTER SYSTEM ARCHIVE LOG CURRENT; Set a parameter to indicate that a failover took place: SQL> EXECUTE DBMS_ROLLING.SET_PARAMETER(name=>'failover', value=>'1'); Revise the upgrade plan: SQL> EXECUTE DBMS_ROLLING.BUILD_PLAN; Resume the rolling upgrade.

SQL> ALTER DATABASE RECOVER MANAGED STANDBY DATABASE CANCEL;
SQL> ALTER DATABASE RECOVER MANAGED STANDBY FINISH;
SQL> ALTER DATABASE FAILOVER TO OAKLAND;
SQL> ALTER DATABASE OPEN;

SQL> ALTER SYSTEM SET LOG_ARCHIVE_DEST_2='service="boston" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, PRIMARY_ROLE)
  3  DB_UNIQUE_NAME="oakland"';

Recover remaining redo on atlanta and failover to the new transient logical role: SQL> ALTER DATABASE RECOVER MANAGED STANDBY FINISH;

SQL> ALTER DATABASE ACTIVATE STANDBY DATABASE;

SQL> ALTER DATABASE OPEN; Configure log archive destinations on atlanta , as necessary: SQL> alter system set log_archive_dest_2='service="seattle" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, PRIMARY_ROLE)
  3  DB_UNIQUE_NAME="atlanta"';

SQL> alter system set log_archive_dest_3='service="oakland" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, PRIMARY_ROLE)
  3  DB_UNIQUE_NAME="atlanta"';

SQL> alter system set log_archive_dest_4='service="miami" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, ALL_ROLES)
  3  DB_UNIQUE_NAME="atlanta"'; Specify atlanta as the new transient logical standby database: SQL> EXECUTE DBMS_ROLLING.SET_PARAMETER(name=>'failover', value=>'1'); Revise the upgrade plan: SQL> EXECUTE DBMS_ROLLING.BUILD_PLAN; Resume the rolling upgrade.

SQL> ALTER DATABASE RECOVER MANAGED STANDBY FINISH;

SQL> ALTER DATABASE ACTIVATE STANDBY DATABASE;

SQL> ALTER DATABASE OPEN;

SQL> alter system set log_archive_dest_2='service="seattle" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, PRIMARY_ROLE)
  3  DB_UNIQUE_NAME="atlanta"';

SQL> alter system set log_archive_dest_3='service="oakland" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, PRIMARY_ROLE)
  3  DB_UNIQUE_NAME="atlanta"';

SQL> alter system set log_archive_dest_4='service="miami" reopen=5
  2  LGWR ASYNC NET_TIMEOUT=180 valid_for=(ONLINE_LOGFILE, ALL_ROLES)
  3  DB_UNIQUE_NAME="atlanta"';
